import os, sys, pty, tty, select, fcntl, termios, struct, time, signal

def run(cmd, keys=b'', cols=80, rows=24, delay=0.35, total=6.0, stdin_data=None):
    pid, fd = pty.fork()
    if pid == 0:
        # child
        try:
            fcntl.ioctl(1, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
        except Exception:
            pass
        env = dict(os.environ)
        env['COLUMNS'] = str(cols)
        env['LINES'] = str(rows)
        env['TERM'] = 'xterm-256color'
        if stdin_data is not None:
            r, w = os.pipe()
            os.write(w, stdin_data)
            os.close(w)
            os.dup2(r, 0)
        os.execvpe(cmd[0], cmd, env)
        os._exit(1)
    out = bytearray()
    start = time.time()
    # initial settle
    time.sleep(delay)
    def drain():
        while True:
            r, _, _ = select.select([fd], [], [], 0.05)
            if not r:
                break
            try:
                d = os.read(fd, 65536)
            except OSError:
                return False
            if not d:
                return False
            out.extend(d)
        return True
    drain()
    marks = [len(out)]
    for k in keys if isinstance(keys, list) else [bytes([c]) for c in keys]:
        try:
            os.write(fd, k)
        except OSError:
            break
        time.sleep(delay)
        if not drain():
            break
        marks.append(len(out))
    # wait for exit
    deadline = time.time() + 1.0
    while time.time() < deadline:
        if not drain():
            break
    try:
        os.kill(pid, signal.SIGKILL)
    except Exception:
        pass
    try:
        os.waitpid(pid, 0)
    except Exception:
        pass
    os.close(fd)
    return bytes(out), marks

if __name__ == '__main__':
    import argparse, ast
    p = argparse.ArgumentParser()
    p.add_argument('--cols', type=int, default=80)
    p.add_argument('--rows', type=int, default=24)
    p.add_argument('--keys', default='')
    p.add_argument('--delay', type=float, default=0.3)
    p.add_argument('--frames', action='store_true')
    p.add_argument('--stdin', default=None)
    p.add_argument('cmd', nargs='+')
    a = p.parse_args()
    keys = a.keys.encode().decode('unicode_escape').encode('latin1')
    sd = None
    if a.stdin is not None:
        sd = open(a.stdin, 'rb').read()
    out, marks = run(a.cmd, keys=keys, cols=a.cols, rows=a.rows, delay=a.delay, stdin_data=sd)
    if a.frames:
        prev = 0
        for i, m in enumerate(marks):
            sys.stdout.write('===== FRAME %d =====\n' % i)
            sys.stdout.write(repr(out[prev:m]) + '\n')
            prev = m
