#!/usr/bin/env python3
"""Extract json-tui frames from raw pty output and pretty-print them."""
import re, sys

def frames(data: bytes):
    # A frame body starts after the ResetPosition sequence and ends at \x1b[?25l
    # Split on the end-of-frame marker.
    parts = data.split(b'\x1b[?25l\x00')
    res = []
    for p in parts[:-1]:
        # strip leading junk up to the last ResetPosition (\r followed by \x1b[1A.. or \x1b[2K)
        # find last occurrence of '\r\x1b[2K' or a run of \x1b[1A
        m = None
        for m2 in re.finditer(rb'\r(?:\x1b\[2K)?(?:\x1b\[1A(?:\x1b\[2K)?)*(?:\x1b\[6n)?', p):
            if m2.end() - m2.start() > 0:
                m = m2
        body = p[m.end():] if m else p
        res.append(body)
    return res

def show(body: bytes, styles=True):
    txt = body.decode('utf-8', 'replace')
    lines = txt.split('\r\r\n') if '\r\r\n' in txt else txt.split('\r\n')
    out = []
    for ln in lines:
        if styles:
            out.append(ln.replace('\x1b', '\\e'))
        else:
            out.append(re.sub(r'\x1b\[[0-9;]*[A-Za-z]', '', ln))
    return '\n'.join(out)

if __name__ == '__main__':
    data = eval(sys.stdin.read())
    fs = frames(data)
    plain = '--plain' in sys.argv
    which = [a for a in sys.argv[1:] if a.lstrip('-').isdigit()]
    idxs = [int(w) for w in which] if which else range(len(fs))
    for i in idxs:
        print('===== FRAME %d =====' % i)
        print(show(fs[i], styles=not plain))

