#!/usr/bin/env python3
"""Drive json-tui in a pty; print each frame as a rendered screen."""
import os, sys, pty, select, fcntl, termios, struct, time, signal, re, argparse

KEYMAP = {
    'up': b'\x1b[A', 'down': b'\x1b[B', 'right': b'\x1b[C', 'left': b'\x1b[D',
    'enter': b'\r', 'esc': b'\x1b', 'tab': b'\t',
    'pgup': b'\x1b[5~', 'pgdn': b'\x1b[6~',
    'home': b'\x1b[H', 'end': b'\x1b[F',
    'plus': b'+', 'minus': b'-', 'q': b'q', 'g': b'g', 'G': b'G',
    'j': b'j', 'k': b'k', 'h': b'h', 'l': b'l',
    'wheelup': b'\x1b[<64;10;5M', 'wheeldown': b'\x1b[<65;10;5M',
}

def parse_keys(spec):
    keys = []
    for tok in spec.split(','):
        tok = tok.strip()
        if not tok:
            continue
        if tok in KEYMAP:
            keys.append(KEYMAP[tok])
        elif tok.startswith('raw:'):
            keys.append(tok[4:].encode().decode('unicode_escape').encode('latin1'))
        elif tok.startswith('click:'):
            _, x, y = tok.split(':')
            keys.append(('\x1b[<0;%s;%sM' % (x, y)).encode())
            keys.append(('\x1b[<0;%s;%sm' % (x, y)).encode())
        else:
            keys.append(tok.encode())
    return keys

def run(cmd, keys, cols, rows, delay, stdin_data):
    pid, fd = pty.fork()
    if pid == 0:
        try:
            fcntl.ioctl(1, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
        except Exception:
            pass
        env = dict(os.environ)
        env['COLUMNS'] = str(cols); env['LINES'] = str(rows); env['TERM'] = 'xterm-256color'
        if stdin_data is not None:
            r, w = os.pipe()
            os.set_blocking(w, False)
            try:
                os.write(w, stdin_data)
            except BlockingIOError:
                pass
            os.close(w)
            os.dup2(r, 0)
        os.execvpe(cmd[0], cmd, env)
        os._exit(1)
    out = bytearray()
    def drain(t=0.12):
        alive = True
        while True:
            r, _, _ = select.select([fd], [], [], t)
            if not r:
                break
            try:
                d = os.read(fd, 65536)
            except OSError:
                alive = False; break
            if not d:
                alive = False; break
            out.extend(d)
            t = 0.05
        return alive
    time.sleep(0.05)
    drain(0.6)
    marks = [len(out)]
    for k in keys:
        try:
            os.write(fd, k)
        except OSError:
            break
        time.sleep(0.02)
        if not drain(delay):
            marks.append(len(out)); break
        marks.append(len(out))
    drain(0.3)
    try:
        os.kill(pid, signal.SIGKILL); os.waitpid(pid, 0)
    except Exception:
        pass
    try:
        os.close(fd)
    except Exception:
        pass
    return bytes(out), marks

class Term:
    def __init__(self, cols, rows):
        self.cols, self.rows = cols, rows
        self.grid = [[(' ', '') for _ in range(cols)] for _ in range(rows)]
        self.x = self.y = 0
        self.style = ''
        self.sgr = []
    def resize_check(self):
        while self.y >= len(self.grid):
            self.grid.append([(' ', '') for _ in range(self.cols)])
    def put(self, ch):
        self.resize_check()
        if self.x < self.cols:
            self.grid[self.y][self.x] = (ch, self.style)
        self.x += 1
    def feed(self, data: str):
        i = 0
        n = len(data)
        while i < n:
            c = data[i]
            if c == '\x1b':
                m = re.match(r'\x1b\[([0-9;?<>]*)([A-Za-z@])', data[i:])
                if m:
                    self.csi(m.group(1), m.group(2))
                    i += m.end(); continue
                m = re.match(r'\x1bP.*?\x1b\\', data[i:], re.S)
                if m:
                    i += m.end(); continue
                m = re.match(r'\x1b\][^\x07]*\x07', data[i:])
                if m:
                    i += m.end(); continue
                m = re.match(r'\x1b\[[0-9;]* q', data[i:])
                if m:
                    i += m.end(); continue
                i += 1; continue
            if c == '\r':
                self.x = 0; i += 1; continue
            if c == '\n':
                self.y += 1; self.resize_check(); i += 1; continue
            if c == '\x00' or c == '\x07':
                i += 1; continue
            self.put(c); i += 1
        return self
    def csi(self, params, cmd):
        ps = [int(p) for p in params.split(';') if p.isdigit()]
        a = ps[0] if ps else 1
        if cmd == 'A': self.y = max(0, self.y - a)
        elif cmd == 'B': self.y += a; self.resize_check()
        elif cmd == 'C': self.x += a
        elif cmd == 'D': self.x = max(0, self.x - a)
        elif cmd == 'H':
            self.y = (ps[0]-1 if len(ps) > 0 else 0); self.x = (ps[1]-1 if len(ps) > 1 else 0)
            self.resize_check()
        elif cmd == 'K':
            self.resize_check()
            k = ps[0] if ps else 0
            rng = range(self.x, self.cols) if k == 0 else (range(0, self.x+1) if k == 1 else range(self.cols))
            for xx in rng:
                self.grid[self.y][xx] = (' ', '')
        elif cmd == 'J':
            pass
        elif cmd == 'm':
            self.setsgr(params)
    def setsgr(self, params):
        codes = [p for p in params.split(';')]
        for p in codes:
            if p == '' or p == '0':
                self.sgr = []
            else:
                v = int(p)
                if v == 39: self.sgr = [s for s in self.sgr if not (30 <= s <= 38 or 90 <= s <= 97)]
                elif v == 49: self.sgr = [s for s in self.sgr if not (40 <= s <= 48 or 100 <= s <= 107)]
                elif v == 22: self.sgr = [s for s in self.sgr if s not in (1, 2)]
                elif v == 23: self.sgr = [s for s in self.sgr if s != 3]
                elif v == 24: self.sgr = [s for s in self.sgr if s != 4]
                elif v == 27: self.sgr = [s for s in self.sgr if s != 7]
                elif v == 28: self.sgr = [s for s in self.sgr if s != 8]
                elif v == 29: self.sgr = [s for s in self.sgr if s != 9]
                else:
                    if 30 <= v <= 38 or 90 <= v <= 97: self.sgr = [s for s in self.sgr if not (30 <= s <= 38 or 90 <= s <= 97)]
                    if 40 <= v <= 48 or 100 <= v <= 107: self.sgr = [s for s in self.sgr if not (40 <= s <= 48 or 100 <= s <= 107)]
                    self.sgr.append(v)
        self.style = ';'.join(str(s) for s in sorted(set(self.sgr)))
    def dump(self, style=False):
        lines = []
        for row in self.grid:
            # trim trailing spaces
            r = row[:]
            while r and r[-1][0] == ' ' and r[-1][1] == '':
                r.pop()
            if not style:
                lines.append(''.join(c for c, _ in r))
            else:
                s = ''
                cur = None
                for ch, st in r:
                    if st != cur:
                        s += '{%s}' % st if st else '{}'
                        cur = st
                    s += ch
                lines.append(s)
        while lines and lines[-1] == '':
            lines.pop()
        return '\n'.join(lines)

def main():
    p = argparse.ArgumentParser()
    p.add_argument('--cols', type=int, default=80)
    p.add_argument('--rows', type=int, default=24)
    p.add_argument('--keys', default='')
    p.add_argument('--delay', type=float, default=0.25)
    p.add_argument('--stdin', default=None)
    p.add_argument('--style', action='store_true')
    p.add_argument('--raw', action='store_true')
    p.add_argument('--last', action='store_true')
    p.add_argument('cmd', nargs='+')
    a = p.parse_args()
    keys = parse_keys(a.keys)
    sd = open(a.stdin, 'rb').read() if a.stdin else None
    out, marks = run(a.cmd, keys, a.cols, a.rows, a.delay, sd)
    if a.raw:
        prev = 0
        for i, m in enumerate(marks):
            print('===== RAW %d =====' % i); print(repr(out[prev:m])); prev = m
        if prev < len(out):
            print('===== RAW TAIL ====='); print(repr(out[prev:]))
        return
    prev = 0
    rng = [len(marks)-1] if a.last else range(len(marks))
    for i in range(len(marks)):
        t = Term(a.cols, a.rows)
        t.feed(out[:marks[i]].decode('utf-8', 'replace'))
        if i in rng or not a.last:
            print('===== SCREEN %d =====' % i)
            print(t.dump(style=a.style))
    if not a.last:
        t = Term(a.cols, a.rows); t.feed(out.decode('utf-8', 'replace'))
        print('===== FINAL ====='); print(t.dump(style=a.style))

main()

